#![allow(non_snake_case, unused_macros)]

use proconio::input;
use rand::prelude::*;
use svg::node::element::{Circle, Rectangle, Definitions, Group, Image, Line, Style, Use};

const PlayerImg: &str = "data:image/png;base64,";
const StoneAImg: &str = "data:image/png;base64,";
const StoneBImg: &str = "data:image/png;base64,";
const StoneCImg: &str = "data:image/png;base64,";
const HoleImg: &str = "data:image/png;base64,";
const BoulderImg: &str = "data:image/png;base64,";

#[derive(Clone, Debug)]
pub struct Input {
    pub n: usize,
    pub m: usize,
    pub c: Vec<String>,
    // pub walls: [[usize; 4]; m]
}

// P: Player
// @: 岩
// #: 岩 + Player
// %: 鉱石a + Player
// &: 鉱石b + Player
// *: 鉱石c + Player
// A,B,C: 穴
// X,Y,Z: それぞれ穴A,B,C + Player
type Board = Vec<Vec<char>>;

impl std::fmt::Display for Input {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "{} {}", self.n, self.m)?;
        // for i in 0..self.n {
        //     writeln!(f, "{} {}", self.a[i], self.b[i])?;
        // }
        Ok(())
    }
}

pub fn parse_input(f: &str) -> Board {
    let f = proconio::source::once::OnceSource::from(f);
    input! {
        from f,
        n: usize,
        m: usize,
        board: [String; 20]
    }

	let mut board_chars: Board = board
		.iter()
		.map(|row| row.chars().collect())
		.collect();

	for row in board_chars.iter_mut() {
		for cell in row.iter_mut() {
			if *cell == 'A' {
				*cell = 'X';
			}
		}
	}

	board_chars
}

pub struct Output {
    pub val: Vec<Board>
}

pub fn find_a_position(board: Board) -> (usize, usize) {

	for (row_index, row) in board.iter().enumerate() {
		for (col_index, cell) in row.iter().enumerate() {
			if *cell == 'A' || *cell == 'X' {
				return (col_index, row_index);
			}
		}
	}

	(0, 0) // 'A'が見つからなかった場合
}

pub fn parse_output(f: &str, initialBoard: Board) -> Output {
    let mut outputs = Output {val: Vec::new() };
	outputs.val.push(initialBoard.clone());

	let mut playerPos = find_a_position(initialBoard);

    for line in f.lines() {
		let parts: Vec<&str> = line.split_whitespace().collect();
		if parts.is_empty() {
			continue;
		}

		match parts[0] {
			"1" => {
			}
			"2" => {
			}
			"3" => {
			}
			_ => {}
		}
    }

	outputs
}

pub fn pos_convert(x: usize, y: usize) -> (f32, f32) {
    let x_f32: f32 = x as f32 * 50.0;
    let y_f32: f32 = y as f32 * 50.0;
    (x_f32, y_f32)
}

pub fn vis(output: &Output, turn: usize) -> (i64, String, String) {
    let mut score = 0;
    // Canvasの設定
    let W = 1000.0;
    let H = 1000.0;
    let mut doc = svg::Document::new()
        .set("id", "vis")
        .set("viewBox", (-5, -5, W + 10.0, H + 10.0))
        .set("width", W + 10.0)
        .set("height", H + 10.0)
        .set("style", "background-color:white");

    doc = doc.add( Definitions::new().add( Image::new() .set("id", "player") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", PlayerImg),),);
    doc = doc.add( Definitions::new().add( Image::new() .set("id", "stone_a") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", StoneAImg),),);
    doc = doc.add( Definitions::new().add( Image::new() .set("id", "stone_b") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", StoneBImg),),);
    doc = doc.add( Definitions::new().add( Image::new() .set("id", "stone_c") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", StoneCImg),),);
    doc = doc.add( Definitions::new().add( Image::new() .set("id", "hole") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", HoleImg),),);
    doc = doc.add( Definitions::new().add( Image::new() .set("id", "boulder") .set("width", 50) .set("height", 50) .set("preserveAspectRatio", "none") .set("href", BoulderImg),),);

	let board:Board = output.val[turn].clone();

	for row in 0..21 {
        doc = doc.add( Line::new() .set("x1", 0) .set("y1", row*50) .set("x2", 1000) .set("y2", row*50) .set("stroke", "#000000"),);
    }
	for col in 0..21 {
        doc = doc.add( Line::new() .set("x1", col*50) .set("y1", 0) .set("x2", col*50) .set("y2", 1000) .set("stroke", "#000000"),);
	}

	for (row_index, row) in board.iter().enumerate() {
		for (col_index, cell) in row.iter().enumerate() {
			let (x, y) = pos_convert(col_index, row_index);
			if *cell == 'A' || *cell == 'B' || *cell == 'C' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#hole")));
			}
			else if *cell == 'a' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#stone_a")));
			}
			else if *cell == 'b' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#stone_b")));
			}
			else if *cell == 'c' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#stone_c")));
			}
			else if *cell == 'c' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#stone_c")));
			}
			else if *cell == 'P' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#player")));
			}
			else if *cell == '@' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#boulder")));
			}
			else if *cell == 'X' || *cell == 'Y' || *cell == 'Z' {
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#hole")));
				doc = doc.add(Group::new().add(Use::new().set("x", x) .set("y", y).set("href", "#player")));
			}
			else {
				// 床だけ
			}
		}
	}

    (score as i64, "".to_string(), doc.to_string())
}
